const inp = $input.first().json;
const llmRaw = inp.output || inp.text || inp.response || inp.content || '';

let intentObj = { intent: null, params: {}, status: 'ASK_CLARIFICATION', missing_fields: ['intent'] };
try {
  const m = llmRaw.match(/{[\s\S]*}/);
  if (m) intentObj = JSON.parse(m[0]);
} catch(e) {
  intentObj = { intent: null, params: {}, status: 'ASK_CLARIFICATION', missing_fields: ['json_parse_error'] };
}

let apiCode = intentObj.intent;
if (apiCode && !apiCode.startsWith('@')) {
    apiCode = '@' + apiCode;
}

let username = 'demo';
try {
  const authHeader = $('Webhook AI Chat').first().json.headers?.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();
  if (token && token.split('.').length === 3) {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf-8'));
    username = payload.Username || payload.username || payload.sub || 'demo';
  }
} catch(e) {}

if (intentObj.status === 'ASK_CLARIFICATION') {
    let msg = 'Dạ, em chưa hiểu ý anh/chị. Anh/chị cần tra cứu thông tin gì ạ?';
    if (intentObj.missing_fields && intentObj.missing_fields.length > 0) {
        if (intentObj.missing_fields.includes('intent') || intentObj.missing_fields.includes('json_parse_error')) {
            return [{ json: { isValid: false, fallbackBody: { status: 'doc_search', message: 'Dạ, để em tra cứu nhanh trong kho tài liệu nội bộ, sếp đợi em xíu nhé... ⏳', apiCode: 'DOC_SEARCH', intent: 'DOC_SEARCH', missing_fields: [] }, _debug_llm: llmRaw.substring(0,50) } }];
        } else {
            msg = 'Dạ, để xử lý yêu cầu, anh/chị cung cấp thêm giúp em thông tin: ' + intentObj.missing_fields.join(', ') + ' nhé!';
        }
    }
    return [{ json: { isValid: false, fallbackBody: { status: 'info', message: msg, apiCode: 'ASK_CLARIFICATION', intent: 'ASK_CLARIFICATION', missing_fields: intentObj.missing_fields }, _debug_llm: llmRaw.substring(0,50) } }];
}

let cleanParams = {};
if (apiCode) cleanParams = Object.assign({}, intentObj.params, { '@Username': username });

function toLocalISO(d) {
    const mm = (d.getMonth() + 1).toString().padStart(2, '0');
    const dd = d.getDate().toString().padStart(2, '0');
    return d.getFullYear() + '-' + mm + '-' + dd;
}
const now = new Date();
const placeholders = { '[TODAY]': toLocalISO(now) };

if (apiCode === '@doanh_so' || apiCode === '@don_hang') {
    if (!cleanParams['@DenNgay']) cleanParams['@DenNgay'] = toLocalISO(now);
    if (!cleanParams['@TuNgay']) {
       const past30 = new Date(now);
       past30.setDate(past30.getDate() - 30);
       cleanParams['@TuNgay'] = toLocalISO(past30);
    }
}

const finalParams = {};
for (const k of Object.keys(cleanParams || {})) {
  let v = cleanParams[k];
  if (v === '' || v === null || v === undefined || v === 'null') continue;
  let newK = k.startsWith('@') ? k : ('@' + k);
  if (typeof v === 'string') {
    if (placeholders[v]) v = placeholders[v];
    if (newK === '@MaKhachHang' || newK === '@MaSP' || newK === '@MaKH') {
       v = v.replace(/\s+/g, '').toUpperCase();
       v = v.replace(/NHÀTHUỐC|KHÁCHHÀNG|NHÂNVIÊN|NT/gi, '');
    }
    if (['CỦA TÔI', 'CỦA MÌNH', 'CỦA EM', 'TÔI'].includes(v.trim().toUpperCase())) continue;
  }
  finalParams[newK] = v;
}

const isValid = !!apiCode;
return [{ json: { apiCode: apiCode, params: finalParams, isComplex: false, username: username, isValid: isValid, _debug_llm: llmRaw.substring(0, 50) } }];

const k0 = $input.first()?.json || {};
const status = k0.status || 'success';
const count = k0.count || 0;
const data = k0.data || [];
const apiCode = $('Parse Intent & Auth').first().json.apiCode || '';

let message = '';
if (status === 'error') {
  message = k0.reply || k0.message || 'Co loi xay ra';
  return [{ json: { status: 'error', message: message, data: [], count: 0, apiCode: apiCode } }];
}

if (count === 0 || data.length === 0) {
  message = 'Khong tim thay du lieu phu hop.';
  return [{ json: { status: 'success', message: message, data: [], count: 0, apiCode: apiCode } }];
}

message = k0.reply || ('Tim thay ' + count + ' ket qua.');
return [{ json: {
  status: 'success',
  message: message,
  data: data,
  count: count,
  apiCode: apiCode
} }];
